00064 QpParam::QpParam(const int           qpy,
00065                  const ComponentID   compID,
00066                  const int           qpBdOffset,
00067                  const int           internalMinusInputBitDepth,
00068                  const int           chromaQPOffset,
00069                  const ChromaFormat  chFmt,
00070                  const int           dqp
00071               ,  const SPS           *sps
00072               , const bool           applyACTQpoffset
00073 )
00074 {
00075   int baseQp;
00076   if (isLuma(compID))
00077   {
00078     baseQp = qpy + qpBdOffset;
00079   }
00080   else
00081   {
00082     int qpi = Clip3(-qpBdOffset, MAX_QP, qpy);
00083     baseQp = sps->getMappedChromaQpValue(compID, qpi);
00084     baseQp = Clip3(-qpBdOffset, MAX_QP, baseQp + chromaQPOffset) + qpBdOffset;
00085   }
00086 
00087   if (applyACTQpoffset)
00088   {
00089     baseQp += DELTA_QP_ACT[compID];
00090   }
00091   baseQp = Clip3( 0, MAX_QP+qpBdOffset, baseQp + dqp );
00092 
00093   Qps[0] =baseQp;
00094   pers[0]=baseQp/6;
00095   rems[0]=baseQp%6;
00096 
00097   int baseQpTS = baseQp;
00098   baseQpTS = std::max(baseQpTS, 4 + 6 * internalMinusInputBitDepth);
00099 
00100   Qps[1]  = baseQpTS;
00101   pers[1] = baseQpTS / 6;
00102   rems[1] = baseQpTS % 6;
00103 }
00104 
00105 QpParam::QpParam(const TransformUnit& tu, const ComponentID &compIDX, const int QP /*= -MAX_INT*/, const bool allowACTQpoffset /*= true*/)
00106 {
00107   int chromaQpOffset = 0;
00108   ComponentID compID = MAP_CHROMA(compIDX);
00109 
00110   if (isChroma(compID))
00111   {
00112     const bool useJQP = ( abs(TU::getICTMode(tu)) == 2 );
00113 
00114     chromaQpOffset += tu.cs->pps->getQpOffset            ( useJQP ? JOINT_CbCr : compID );
00115     chromaQpOffset += tu.cu->slice->getSliceChromaQpDelta( useJQP ? JOINT_CbCr : compID );
00116 
00117     chromaQpOffset += tu.cs->pps->getChromaQpOffsetListEntry( tu.cu->chromaQpAdj ).u.offset[int( useJQP ? JOINT_CbCr : compID ) - 1];
00118   }
00119 
00120   int dqp = 0;
00121 
00122   const bool useJQP = isChroma(compID) && (abs(TU::getICTMode(tu)) == 2);
00123   bool applyACTQpoffset = tu.cu->colorTransform && allowACTQpoffset;
00124   *this = QpParam(QP <= -MAX_INT ? tu.cu->qp : QP, useJQP ? JOINT_CbCr : compID, tu.cs->sps->getQpBDOffset(toChannelType(compID)), tu.cs->sps->getInternalMinusInputBitDepth(toChannelType(compID)), chromaQpOffset, tu.chromaFormat, dqp, tu.cs->sps, applyACTQpoffset);
00125 }
