00142 void invResDPCM( const TransformUnit &tu, const ComponentID &compID, CoeffBuf &dstBuf )
00143 {
00144   const CompArea &rect = tu.blocks[compID];
00145   const int      wdt = rect.width;
00146   const int      hgt = rect.height;
00147   const CCoeffBuf coeffs = tu.getCoeffs(compID);
00148 
00149   const int      maxLog2TrDynamicRange = tu.cs->sps->getMaxLog2TrDynamicRange(toChannelType(compID));
00150   const TCoeff   inputMinimum   = -(1 << maxLog2TrDynamicRange);
00151   const TCoeff   inputMaximum   =  (1 << maxLog2TrDynamicRange) - 1;
00152 
00153   const TCoeff* coef = &coeffs.buf[0];
00154   TCoeff* dst = &dstBuf.buf[0];
00155 
00156   if( isLuma(compID) ? tu.cu->bdpcmMode == 1 : tu.cu->bdpcmModeChroma == 1)
00157   {
00158     for( int y = 0; y < hgt; y++ )
00159     {
00160       dst[0] = coef[0];
00161       for( int x = 1; x < wdt; x++ )
00162       {
00163         dst[x] = Clip3(inputMinimum, inputMaximum, dst[x - 1] + coef[x]);
00164       }
00165       coef += coeffs.stride;
00166       dst += dstBuf.stride;
00167     }
00168   }
00169   else
00170   {
00171     for( int x = 0; x < wdt; x++ )
00172     {
00173       dst[x] = coef[x];
00174     }
00175     for( int y = 0; y < hgt - 1; y++ )
00176     {
00177       for( int x = 0; x < wdt; x++ )
00178       {
00179         dst[dstBuf.stride + x] = Clip3(inputMinimum, inputMaximum, dst[x] + coef[coeffs.stride + x]);
00180       }
00181       coef += coeffs.stride;
00182       dst += dstBuf.stride;
00183     }
00184   }
00185 }
00186 
00187 void fwdResDPCM( TransformUnit &tu, const ComponentID &compID )
00188 {
00189   const CompArea &rect = tu.blocks[compID];
00190   const int      wdt = rect.width;
00191   const int      hgt = rect.height;
00192   CoeffBuf       coeffs = tu.getCoeffs(compID);
00193 
00194   TCoeff* coef = &coeffs.buf[0];
00195 
00196   if( isLuma(compID) ? tu.cu->bdpcmMode == 1 : tu.cu->bdpcmModeChroma == 1)
00197   {
00198     for( int y = 0; y < hgt; y++ )
00199     {
00200       for( int x = wdt - 1; x > 0; x-- )
00201       {
00202         coef[x] -= coef[x - 1];
00203       }
00204       coef += coeffs.stride;
00205     }
00206   }
00207   else
00208   {
00209     coef += coeffs.stride * (hgt - 1);
00210     for( int y = 0; y < hgt - 1; y++ )
00211     {
00212       for ( int x = 0; x < wdt; x++ )
00213       {
00214         coef[x] -= coef[x - coeffs.stride];
00215       }
00216       coef -= coeffs.stride;
00217     }
00218   }
00219 }
