00221 // To minimize the distortion only. No rate is considered.
00222 void Quant::xSignBitHidingHDQ( TCoeff* pQCoef, const TCoeff* pCoef, TCoeff* deltaU, const CoeffCodingContext& cctx, const int maxLog2TrDynamicRange )
00223 {
00224   const uint32_t width     = cctx.width();
00225   const uint32_t height    = cctx.height();
00226   const uint32_t groupSize = 1 << cctx.log2CGSize();
00227 
00228   const TCoeff entropyCodingMinimum = -(1 << maxLog2TrDynamicRange);
00229   const TCoeff entropyCodingMaximum =  (1 << maxLog2TrDynamicRange) - 1;
00230 
00231   int lastCG = -1;
00232   int absSum = 0 ;
00233   int n ;
00234 
00235   for( int subSet = (width*height-1) >> cctx.log2CGSize(); subSet >= 0; subSet-- )
00236   {
00237     int  subPos = subSet << cctx.log2CGSize();
00238     int  firstNZPosInCG=groupSize , lastNZPosInCG=-1 ;
00239     absSum = 0 ;
00240 
00241     for(n = groupSize-1; n >= 0; --n )
00242     {
00243       if( pQCoef[ cctx.blockPos( n + subPos ) ] )
00244       {
00245         lastNZPosInCG = n;
00246         break;
00247       }
00248     }
00249 
00250     for(n = 0; n <groupSize; n++ )
00251     {
00252       if( pQCoef[ cctx.blockPos( n + subPos ) ] )
00253       {
00254         firstNZPosInCG = n;
00255         break;
00256       }
00257     }
00258 
00259     for(n = firstNZPosInCG; n <=lastNZPosInCG; n++ )
00260     {
00261       absSum += int(pQCoef[ cctx.blockPos( n + subPos ) ]);
00262     }
00263 
00264     if(lastNZPosInCG>=0 && lastCG==-1)
00265     {
00266       lastCG = 1 ;
00267     }
00268 
00269     if( lastNZPosInCG-firstNZPosInCG>=SBH_THRESHOLD )
00270     {
00271       uint32_t signbit = (pQCoef[cctx.blockPos(subPos+firstNZPosInCG)]>0?0:1) ;
00272       if( signbit!=(absSum&0x1) )  //compare signbit with sum_parity
00273       {
00274         TCoeff curCost    = std::numeric_limits<TCoeff>::max();
00275         TCoeff minCostInc = std::numeric_limits<TCoeff>::max();
00276         int minPos =-1, finalChange=0, curChange=0;
00277 
00278         for( n = (lastCG==1?lastNZPosInCG:groupSize-1) ; n >= 0; --n )
00279         {
00280           uint32_t blkPos   = cctx.blockPos( n+subPos );
00281           if(pQCoef[ blkPos ] != 0 )
00282           {
00283             if(deltaU[blkPos]>0)
00284             {
00285               curCost = - deltaU[blkPos];
00286               curChange=1 ;
00287             }
00288             else
00289             {
00290               //curChange =-1;
00291               if(n==firstNZPosInCG && abs(pQCoef[blkPos])==1)
00292               {
00293                 curCost = std::numeric_limits<TCoeff>::max();
00294               }
00295               else
00296               {
00297                 curCost = deltaU[blkPos];
00298                 curChange =-1;
00299               }
00300             }
00301           }
00302           else
00303           {
00304             if(n<firstNZPosInCG)
00305             {
00306               uint32_t thisSignBit = (pCoef[blkPos]>=0?0:1);
00307               if(thisSignBit != signbit )
00308               {
00309                 curCost = std::numeric_limits<TCoeff>::max();
00310               }
00311               else
00312               {
00313                 curCost = - (deltaU[blkPos])  ;
00314                 curChange = 1 ;
00315               }
00316             }
00317             else
00318             {
00319               curCost = - (deltaU[blkPos])  ;
00320               curChange = 1 ;
00321             }
00322           }
00323 
00324           if( curCost<minCostInc)
00325           {
00326             minCostInc = curCost ;
00327             finalChange = curChange ;
00328             minPos = blkPos ;
00329           }
00330         } //CG loop
00331 
00332         if(pQCoef[minPos] == entropyCodingMaximum || pQCoef[minPos] == entropyCodingMinimum)
00333         {
00334           finalChange = -1;
00335         }
00336 
00337         if(pCoef[minPos]>=0)
00338         {
00339           pQCoef[minPos] += finalChange ;
00340         }
00341         else
00342         {
00343           pQCoef[minPos] -= finalChange ;
00344         }
00345       } // Hide
00346     }
00347     if(lastCG==1)
00348     {
00349       lastCG=0 ;
00350     }
00351   } // TU loop
00352 
00353   return;
00354 }
