00356 void Quant::dequant(const TransformUnit &tu,
00357                              CoeffBuf      &dstCoeff,
00358                        const ComponentID   &compID,
00359                        const QpParam       &cQP)
00360 {
00361   const SPS            *sps                = tu.cs->sps;
00362   const CompArea       &area               = tu.blocks[compID];
00363   const uint32_t            uiWidth            = area.width;
00364   const uint32_t            uiHeight           = area.height;
00365         TCoeff   *const piCoef             = dstCoeff.buf;
00366   const uint32_t            numSamplesInBlock  = uiWidth * uiHeight;
00367   const int             maxLog2TrDynamicRange = sps->getMaxLog2TrDynamicRange(toChannelType(compID));
00368   const TCoeff          transformMinimum   = -(1 << maxLog2TrDynamicRange);
00369   const TCoeff          transformMaximum   =  (1 << maxLog2TrDynamicRange) - 1;
00370   const bool            isTransformSkip = (tu.mtsIdx[compID] == MTS_SKIP);
00371 
00372   const bool            disableSMForLFNST = tu.cs->slice->getExplicitScalingListUsed() ? tu.cs->slice->getSPS()->getDisableScalingMatrixForLfnstBlks() : false;
00373   const bool            isLfnstApplied = tu.cu->lfnstIdx > 0 && (tu.cu->isSepTree() ? true : isLuma(compID));
00374   const bool            disableSMForACT = tu.cs->slice->getSPS()->getScalingMatrixForAlternativeColourSpaceDisabledFlag() && (tu.cs->slice->getSPS()->getScalingMatrixDesignatedColourSpaceFlag() == tu.cu->colorTransform);
00375   const bool            enableScalingLists = getUseScalingList(uiWidth, uiHeight, isTransformSkip, isLfnstApplied, disableSMForLFNST, disableSMForACT);
00376   const int             scalingListType    = getScalingListType(tu.cu->predMode, compID);
00377   const int             channelBitDepth    = sps->getBitDepth(toChannelType(compID));
00378 
00379   const TCoeff          *coef;
00380   if ((tu.cu->bdpcmMode && isLuma(compID)) || ( tu.cu->bdpcmModeChroma && isChroma(compID) ))
00381   {
00382     invResDPCM( tu, compID, dstCoeff );
00383     coef = piCoef;
00384   }
00385   else
00386   {
00387     coef = tu.getCoeffs(compID).buf;
00388   }
00389   const TCoeff          *const piQCoef = coef;
00390   CHECK(scalingListType >= SCALING_LIST_NUM, "Invalid scaling list");
00391   CHECK(uiWidth > m_uiMaxTrSize, "Unsupported transformation size");
00392 
00393   // Represents scaling through forward transform
00394   const bool bClipTransformShiftTo0 = tu.mtsIdx[compID] != MTS_SKIP && sps->getSpsRangeExtension().getExtendedPrecisionProcessingFlag();
00395   const int  originalTransformShift = getTransformShift(channelBitDepth, area.size(), maxLog2TrDynamicRange);
00396   const bool needSqrtAdjustment     = TU::needsBlockSizeTrafoScale( tu, compID );
00397   const int  iTransformShift        = (bClipTransformShiftTo0 ? std::max<int>(0, originalTransformShift) : originalTransformShift) + (needSqrtAdjustment?-1:0);
00398 
00399   const int QP_per = cQP.per(isTransformSkip);
00400   const int QP_rem = cQP.rem(isTransformSkip);
00401 
00402   const int  rightShift = (IQUANT_SHIFT - ((isTransformSkip ? 0 : iTransformShift) + QP_per)) + (enableScalingLists ? LOG2_SCALING_LIST_NEUTRAL_VALUE : 0);
00403 
00404   if(enableScalingLists)
00405   {
00406     //from the dequantization equation:
00407     //iCoeffQ                         = ((Intermediate_Int(clipQCoef) * piDequantCoef[deQuantIdx]) + iAdd ) >> rightShift
00408     //(sizeof(Intermediate_Int) * 8)  =              inputBitDepth    +    dequantCoefBits                   - rightShift
00409     const uint32_t             dequantCoefBits     = 1 + IQUANT_SHIFT + SCALING_LIST_BITS;
00410     const uint32_t             targetInputBitDepth = std::min<uint32_t>((maxLog2TrDynamicRange + 1), (((sizeof(Intermediate_Int) * 8) + rightShift) - dequantCoefBits));
00411 
00412     const Intermediate_Int inputMinimum        = -(1 << (targetInputBitDepth - 1));
00413     const Intermediate_Int inputMaximum        =  (1 << (targetInputBitDepth - 1)) - 1;
00414 
00415     const uint32_t uiLog2TrWidth  = floorLog2(uiWidth);
00416     const uint32_t uiLog2TrHeight = floorLog2(uiHeight);
00417     int *piDequantCoef        = getDequantCoeff(scalingListType, QP_rem, uiLog2TrWidth, uiLog2TrHeight);
00418 
00419     if(rightShift > 0)
00420     {
00421       const Intermediate_Int iAdd = (Intermediate_Int) 1 << (rightShift - 1);
00422 
00423       for( int n = 0; n < numSamplesInBlock; n++ )
00424       {
00425         const TCoeff           clipQCoef = TCoeff(Clip3<Intermediate_Int>(inputMinimum, inputMaximum, piQCoef[n]));
00426         const Intermediate_Int iCoeffQ   = ((Intermediate_Int(clipQCoef) * piDequantCoef[n]) + iAdd ) >> rightShift;
00427 
00428         piCoef[n] = TCoeff(Clip3<Intermediate_Int>(transformMinimum,transformMaximum,iCoeffQ));
00429       }
00430     }
00431     else
00432     {
00433       const int leftShift = -rightShift;
00434 
00435       for( int n = 0; n < numSamplesInBlock; n++ )
00436       {
00437         const TCoeff           clipQCoef = TCoeff(Clip3<Intermediate_Int>(inputMinimum, inputMaximum, piQCoef[n]));
00438         const Intermediate_Int iCoeffQ   = (Intermediate_Int(clipQCoef) * piDequantCoef[n]) << leftShift;
00439 
00440         piCoef[n] = TCoeff(Clip3<Intermediate_Int>(transformMinimum,transformMaximum,iCoeffQ));
00441       }
00442     }
00443   }
00444   else
00445   {
00446     const int scale     = g_invQuantScales[needSqrtAdjustment?1:0][QP_rem];
00447     const int scaleBits = ( IQUANT_SHIFT + 1 );
00448 
00449     //from the dequantisation equation:
00450     //iCoeffQ                         = Intermediate_Int((int64_t(clipQCoef) * scale + iAdd) >> rightShift);
00451     //(sizeof(Intermediate_Int) * 8)  =                    inputBitDepth   + scaleBits      - rightShift
00452     const uint32_t             targetInputBitDepth = std::min<uint32_t>((maxLog2TrDynamicRange + 1), (((sizeof(Intermediate_Int) * 8) + rightShift) - scaleBits));
00453     const Intermediate_Int inputMinimum        = -(1 << (targetInputBitDepth - 1));
00454     const Intermediate_Int inputMaximum        =  (1 << (targetInputBitDepth - 1)) - 1;
00455 
00456     if (rightShift > 0)
00457     {
00458       const Intermediate_Int iAdd = (Intermediate_Int) 1 << (rightShift - 1);
00459 
00460       for( int n = 0; n < numSamplesInBlock; n++ )
00461       {
00462         const TCoeff           clipQCoef = TCoeff(Clip3<Intermediate_Int>(inputMinimum, inputMaximum, piQCoef[n]));
00463         const Intermediate_Int iCoeffQ   = (Intermediate_Int(clipQCoef) * scale + iAdd) >> rightShift;
00464 
00465         piCoef[n] = TCoeff(Clip3<Intermediate_Int>(transformMinimum,transformMaximum,iCoeffQ));
00466       }
00467     }
00468     else
00469     {
00470       const int leftShift = -rightShift;
00471 
00472       for( int n = 0; n < numSamplesInBlock; n++ )
00473       {
00474         const TCoeff           clipQCoef = TCoeff(Clip3<Intermediate_Int>(inputMinimum, inputMaximum, piQCoef[n]));
00475         const Intermediate_Int iCoeffQ   = (Intermediate_Int(clipQCoef) * scale) << leftShift;
00476 
00477         piCoef[n] = TCoeff(Clip3<Intermediate_Int>(transformMinimum,transformMaximum,iCoeffQ));
00478       }
00479     }
00480   }
00481 }
