00518 void Quant::setScalingList(ScalingList *scalingList, const int maxLog2TrDynamicRange[MAX_NUM_CHANNEL_TYPE], const BitDepths &bitDepths)
00519 {
00520   const int minimumQp = 0;
00521   const int maximumQp = SCALING_LIST_REM_NUM;
00522 
00523   int scalingListId = 0;
00524   int recScalingListId = 0;
00525   for(uint32_t size = SCALING_LIST_FIRST_CODED; size <= SCALING_LIST_LAST_CODED; size++) //2x2->64x64
00526   {
00527     for(uint32_t list = 0; list < SCALING_LIST_NUM; list++)
00528     {
00529       if (size == SCALING_LIST_2x2 && list < 4)   // skip 2x2 luma
00530         continue;
00531       scalingListId = g_scalingListId[size][list];
00532       if (scalingList->getChromaScalingListPresentFlag() || scalingList->isLumaScalingList(scalingListId))
00533       {
00534         for(int qp = minimumQp; qp < maximumQp; qp++)
00535         {
00536           xSetScalingListEnc(scalingList, list, size, qp, scalingListId);
00537           xSetScalingListDec(*scalingList, list, size, qp, scalingListId);
00538         }
00539       }
00540       else // chroma QMs in 400
00541       {
00542          scalingList->processDefaultMatrix(scalingListId);
00543       }
00544     }
00545   }
00546   //based on square result and apply downsample technology
00547   for (uint32_t sizew = 0; sizew <= SCALING_LIST_LAST_CODED; sizew++) //7
00548   {
00549     for (uint32_t sizeh = 0; sizeh <= SCALING_LIST_LAST_CODED; sizeh++) //7
00550     {
00551       if (sizew == sizeh || (sizew == SCALING_LIST_1x1 && sizeh<SCALING_LIST_4x4) || (sizeh == SCALING_LIST_1x1 && sizew<SCALING_LIST_4x4)) continue;
00552       for (uint32_t list = 0; list < SCALING_LIST_NUM; list++) //9
00553       {
00554         int largerSide = (sizew > sizeh) ? sizew : sizeh;
00555         if (largerSide < SCALING_LIST_4x4) printf("Rectangle Error !\n");
00556         recScalingListId = g_scalingListId[largerSide][list];
00557         for (int qp = minimumQp; qp < maximumQp; qp++)
00558         {
00559           xSetRecScalingListEnc(scalingList, list, sizew, sizeh, qp, recScalingListId);
00560           xSetRecScalingListDec(*scalingList, list, sizew, sizeh, qp, recScalingListId);
00561         }
00562       }
00563     }
00564   }
00565 }
00570 void Quant::setScalingListDec(const ScalingList &scalingList)
00571 {
00572   const int minimumQp = 0;
00573   const int maximumQp = SCALING_LIST_REM_NUM;
00574 
00575   int scalingListId = 0;
00576   int recScalingListId = 0;
00577   for (uint32_t size = SCALING_LIST_FIRST_CODED; size <= SCALING_LIST_LAST_CODED; size++)
00578   {
00579     for(uint32_t list = 0; list < SCALING_LIST_NUM; list++)
00580     {
00581       if (size == SCALING_LIST_2x2 && list < 4)   // skip 2x2 luma
00582         continue;
00583       scalingListId = g_scalingListId[size][list];
00584       for(int qp = minimumQp; qp < maximumQp; qp++)
00585       {
00586         xSetScalingListDec(scalingList, list, size, qp, scalingListId);
00587       }
00588     }
00589   }
00590   //based on square result and apply downsample technology
00591   //based on square result and apply downsample technology
00592   for (uint32_t sizew = 0; sizew <= SCALING_LIST_LAST_CODED; sizew++) //7
00593   {
00594     for (uint32_t sizeh = 0; sizeh <= SCALING_LIST_LAST_CODED; sizeh++) //7
00595     {
00596       if (sizew == sizeh || (sizew == SCALING_LIST_1x1 && sizeh<SCALING_LIST_4x4) || (sizeh == SCALING_LIST_1x1 && sizew<SCALING_LIST_4x4)) continue;
00597       for (uint32_t list = 0; list < SCALING_LIST_NUM; list++) //9
00598       {
00599         int largerSide = (sizew > sizeh) ? sizew : sizeh;
00600         if (largerSide < SCALING_LIST_4x4) printf("Rectangle Error !\n");
00601         recScalingListId = g_scalingListId[largerSide][list];
00602         for (int qp = minimumQp; qp < maximumQp; qp++)
00603         {
00604           xSetRecScalingListDec(scalingList, list, sizew, sizeh, qp, recScalingListId);
00605         }
00606       }
00607     }
00608   }
00609 }
