00619 void Quant::xSetScalingListEnc(ScalingList *scalingList, uint32_t listId, uint32_t sizeId, int qp, uint32_t scalingListId)
00620 {
00621   uint32_t width  = g_scalingListSizeX[sizeId];
00622   uint32_t height = g_scalingListSizeX[sizeId];
00623   uint32_t ratio  = g_scalingListSizeX[sizeId]/std::min(MAX_MATRIX_SIZE_NUM,(int)g_scalingListSizeX[sizeId]);
00624   int *quantcoeff;
00625   int *coeff = scalingList->getScalingListAddress(scalingListId);
00626   quantcoeff  = getQuantCoeff(listId, qp, sizeId, sizeId);
00627 
00628   const bool blockIsNotPowerOf4 = ((floorLog2(width) + floorLog2(height)) & 1) == 1;
00629   int quantScales = g_quantScales[blockIsNotPowerOf4?1:0][qp];
00630 
00631   processScalingListEnc(coeff,
00632                         quantcoeff,
00633                         (quantScales << LOG2_SCALING_LIST_NEUTRAL_VALUE),
00634                         height, width, ratio,
00635                         std::min(MAX_MATRIX_SIZE_NUM, (int)g_scalingListSizeX[sizeId]),
00636                         scalingList->getScalingListDC(scalingListId));
00637 }
