00646 void Quant::xSetScalingListDec(const ScalingList &scalingList, uint32_t listId, uint32_t sizeId, int qp, uint32_t scalingListId)
00647 {
00648   uint32_t width  = g_scalingListSizeX[sizeId];
00649   uint32_t height = g_scalingListSizeX[sizeId];
00650   uint32_t ratio  = g_scalingListSizeX[sizeId]/std::min(MAX_MATRIX_SIZE_NUM,(int)g_scalingListSizeX[sizeId]);
00651   int *dequantcoeff;
00652   const int *coeff = scalingList.getScalingListAddress(scalingListId);
00653 
00654   dequantcoeff = getDequantCoeff(listId, qp, sizeId, sizeId);
00655 
00656   const bool blockIsNotPowerOf4 = ((floorLog2(width) + floorLog2(height)) & 1) == 1;
00657   int invQuantScale = g_invQuantScales[blockIsNotPowerOf4?1:0][qp];
00658 
00659   processScalingListDec(coeff,
00660                         dequantcoeff,
00661                         invQuantScale,
00662                         height, width, ratio,
00663                         std::min(MAX_MATRIX_SIZE_NUM, (int)g_scalingListSizeX[sizeId]),
00664                         scalingList.getScalingListDC(scalingListId));
