00674 void Quant::xSetRecScalingListEnc(ScalingList *scalingList, uint32_t listId, uint32_t sizeIdw, uint32_t sizeIdh, int qp, uint32_t scalingListId)
00675 {
00676   if (sizeIdw == sizeIdh) return;
00677 
00678   uint32_t width = g_scalingListSizeX[sizeIdw];
00679   uint32_t height = g_scalingListSizeX[sizeIdh];
00680   uint32_t largeSideId = (sizeIdw > sizeIdh) ? sizeIdw : sizeIdh;  //16
00681   int *quantcoeff;
00682   int *coeff = scalingList->getScalingListAddress(scalingListId);//4x4, 8x8
00683   quantcoeff = getQuantCoeff(listId, qp, sizeIdw, sizeIdh);//final quantCoeff (downsample)
00684   const bool blockIsNotPowerOf4 = ((floorLog2(width) + floorLog2(height)) & 1) == 1;
00685   int quantScales = g_quantScales[blockIsNotPowerOf4?1:0][qp];
00686 
00687   processScalingListEnc(coeff,
00688     quantcoeff,
00689     (quantScales << LOG2_SCALING_LIST_NEUTRAL_VALUE),
00690     height, width,
00691     ((largeSideId>3) ? 2 : 1),
00692     ((largeSideId >= 3) ? 8 : 4),
00693     scalingList->getScalingListDC(scalingListId));
00694 }
