00749 void Quant::xSetFlatScalingList(uint32_t list, uint32_t sizeX, uint32_t sizeY, int qp)
00750 {
00751   uint32_t i,num = g_scalingListSizeX[sizeX]*g_scalingListSizeX[sizeY];
00752   int *quantcoeff;
00753   int *dequantcoeff;
00754 
00755   const bool blockIsNotPowerOf4 = ((floorLog2(g_scalingListSizeX[sizeX]) + floorLog2(g_scalingListSizeX[sizeY])) & 1) == 1;
00756   int quantScales    = g_quantScales   [blockIsNotPowerOf4?1:0][qp];
00757   int invQuantScales = g_invQuantScales[blockIsNotPowerOf4?1:0][qp] << 4;
00758 
00759   quantcoeff   = getQuantCoeff(list, qp, sizeX, sizeY);
00760   dequantcoeff = getDequantCoeff(list, qp, sizeX, sizeY);
00761 
00762   for(i=0;i<num;i++)
00763   {
00764     *quantcoeff++ = quantScales;
00765     *dequantcoeff++ = invQuantScales;
