00768 
00779 void Quant::processScalingListEnc( int *coeff, int *quantcoeff, int quantScales, uint32_t height, uint32_t width, uint32_t ratio, int sizuNum, uint32_t dc)
00780 {
00781   if (height != width)
00782   {
00783     for (uint32_t j = 0; j<height; j++)
00784     {
00785       for (uint32_t i = 0; i<width; i++)
00786       {
00787         if (j >= JVET_C0024_ZERO_OUT_TH || i >= JVET_C0024_ZERO_OUT_TH)
00788         {
00789           quantcoeff[j*width + i] = 0;
00790           continue;
00791         }
00792         int ratioWH = (height>width) ? height / width : width / height;
00793         int ratioH = (height / sizuNum) ? (height / sizuNum) : (sizuNum / height); // 32/8 = 4
00794         int ratioW = (width / sizuNum) ? (width / sizuNum) : (sizuNum / width); //16/8 = 2 //sizeNum = 8/4
00795         if (height > width)
00796         {
00797           quantcoeff[j*width + i] = quantScales / coeff[sizuNum * (j / ratioH) + ((i * ratioWH) / ratioH)];
00798         }
00799         else //ratioH < ratioW
00800         {
00801           quantcoeff[j*width + i] = quantScales / coeff[sizuNum * ((j * ratioWH) / ratioW) + (i / ratioW)];
00802         }
00803         int largeOne = (width > height) ? width : height;
00804         if (largeOne>8)
00805         {
00806           quantcoeff[0] = quantScales / dc;
00807         }
00808       }
00809     }
00810     return;
00811   }
00812   for(uint32_t j=0;j<height;j++)
00813   {
00814     for(uint32_t i=0;i<width;i++)
00815     {
00816       quantcoeff[j*width + i] = quantScales / coeff[sizuNum * (j / ratio) + i / ratio];
00817     }
00818   }
00819 
00820   if(ratio > 1)
00821   {
00822     quantcoeff[0] = quantScales / dc;
00823   }
00824 }
00825 
00826 void Quant::processScalingListDec( const int *coeff, int *dequantcoeff, int invQuantScales, uint32_t height, uint32_t width, uint32_t ratio, int sizeNum, uint32_t dc)
00827 {
00828   if (height != width)
00829   {
00830     int ratioWH = (height > width  ) ? (height / width  ) : (width   / height);
00831     int ratioH  = (height / sizeNum) ? (height / sizeNum) : (sizeNum / height);
00832     int ratioW  = (width  / sizeNum) ? (width  / sizeNum) : (sizeNum / width );
00833     if (height > width)
00834     {
00835       for (uint32_t j = 0; j < height; j++)
00836       {
00837         int coeffLineSep        = (j / ratioH) * sizeNum;
00838         int dequantCoeffLineSep = j * width;
00839         for (uint32_t i = 0; i < width; i++)
00840         {
00841           if (i >= JVET_C0024_ZERO_OUT_TH || j >= JVET_C0024_ZERO_OUT_TH)
00842           {
00843             dequantcoeff[dequantCoeffLineSep + i] = 0;
00844             continue;
00845           }
00846           dequantcoeff[dequantCoeffLineSep + i] = invQuantScales * coeff[coeffLineSep + ((i * ratioWH) / ratioH)];
00847         }
00848       }
00849     }
00850     else  //ratioH < ratioW
00851     {
00852       for (uint32_t j = 0; j < height; j++)
00853       {
00854         int coeffLineSep        = ((j * ratioWH) / ratioW) * sizeNum;
00855         int dequantCoeffLineSep = j * width;
00856         for (uint32_t i = 0; i < width; i++)
00857         {
00858           if (i >= JVET_C0024_ZERO_OUT_TH || j >= JVET_C0024_ZERO_OUT_TH)
00859           {
00860             dequantcoeff[dequantCoeffLineSep + i] = 0;
00861             continue;
00862           }
00863           dequantcoeff[dequantCoeffLineSep + i] = invQuantScales * coeff[coeffLineSep + (i / ratioW)];
00864         }
00865       }
00866     }
00867     int largeOne = (width > height) ? width : height;
00868     if (largeOne > 8)
00869       dequantcoeff[0] = invQuantScales * dc;
00870     return;
00871   }
00872   for (uint32_t j = 0; j<height; j++)
00873   {
00874     int coeffLineSep        = (j / ratio) * sizeNum;
00875     int dequantCoeffLineSep = j * width;
00876     for (uint32_t i = 0; i<width; i++)
00877     {
00878       dequantcoeff[dequantCoeffLineSep + i] = invQuantScales * coeff[coeffLineSep + i / ratio];
00879     }
00880   }
00881 
00882   if (ratio > 1)
00883   {
00884     dequantcoeff[0] = invQuantScales * dc;
00885   }
00886 }
00887 
00890 void Quant::xInitScalingList( const Quant* other )
00891 {
00892   m_isScalingListOwner = other == nullptr;
00893 
00894   size_t numElements = 0;
00895 
00896   for (uint32_t sizeIdX = 0; sizeIdX < SCALING_LIST_SIZE_NUM; sizeIdX++)
00897   {
00898     for (uint32_t sizeIdY = 0; sizeIdY < SCALING_LIST_SIZE_NUM; sizeIdY++)
00899     {
00900       for (uint32_t qp = 0; qp < SCALING_LIST_REM_NUM; qp++)
00901       {
00902         for (uint32_t listId = 0; listId < SCALING_LIST_NUM; listId++)
00903         {
00904           numElements += g_scalingListSizeX[sizeIdX] * g_scalingListSizeX[sizeIdY];
00905         }
00906       }
00907     }
00908   }
00909 
00910   if (m_isScalingListOwner)
00911   {
00912     m_quantCoef[0][0][0][0] = new int[2 * numElements];
00913   }
00914 
00915   size_t offset = 0;
00916 
00917   for(uint32_t sizeIdX = 0; sizeIdX < SCALING_LIST_SIZE_NUM; sizeIdX++)
00918   {
00919     for(uint32_t sizeIdY = 0; sizeIdY < SCALING_LIST_SIZE_NUM; sizeIdY++)
00920     {
00921       for(uint32_t qp = 0; qp < SCALING_LIST_REM_NUM; qp++)
00922       {
00923         for(uint32_t listId = 0; listId < SCALING_LIST_NUM; listId++)
00924         {
00925           if( m_isScalingListOwner )
00926           {
00927             m_quantCoef[sizeIdX][sizeIdY][listId][qp] = m_quantCoef[0][0][0][0] + offset;
00928             offset += g_scalingListSizeX[sizeIdX] * g_scalingListSizeX[sizeIdY];
00929             m_dequantCoef[sizeIdX][sizeIdY][listId][qp] = m_quantCoef[0][0][0][0] + offset;
00930             offset += g_scalingListSizeX[sizeIdX] * g_scalingListSizeX[sizeIdY];
00931           }
00932           else
00933           {
00934             m_quantCoef   [sizeIdX][sizeIdY][listId][qp] = other->m_quantCoef   [sizeIdX][sizeIdY][listId][qp];
00935             m_dequantCoef [sizeIdX][sizeIdY][listId][qp] = other->m_dequantCoef [sizeIdX][sizeIdY][listId][qp];
00936           }
00937         } // listID loop
00938       }
00939     }
00940   }
00941 
00942   m_pairCheck = 0;
00943 }
00944 
00947 void Quant::xDestroyScalingList()
00948 {
00949   if( !m_isScalingListOwner ) return;
00950 
00951   delete[] m_quantCoef[0][0][0][0];
00952 }
00953 
00954 void Quant::quant(TransformUnit &tu, const ComponentID &compID, const CCoeffBuf &pSrc, TCoeff &uiAbsSum, const QpParam &cQP, const Ctx& ctx)
00955 {
00956   const SPS &sps            = *tu.cs->sps;
00957   const CompArea &rect      = tu.blocks[compID];
00958   const uint32_t uiWidth        = rect.width;
00959   const uint32_t uiHeight       = rect.height;
00960   const int channelBitDepth = sps.getBitDepth(toChannelType(compID));
00961 
00962   const CCoeffBuf &piCoef   = pSrc;
00963         CoeffBuf   piQCoef  = tu.getCoeffs(compID);
00964 
00965   const bool useTransformSkip      = (tu.mtsIdx[compID] == MTS_SKIP);
00966   const int  maxLog2TrDynamicRange = sps.getMaxLog2TrDynamicRange(toChannelType(compID));
00967 
00968   {
00969     CoeffCodingContext cctx(tu, compID, tu.cs->slice->getSignDataHidingEnabledFlag());
00970     const TCoeff entropyCodingMinimum = -(1 << maxLog2TrDynamicRange);
00971     const TCoeff entropyCodingMaximum =  (1 << maxLog2TrDynamicRange) - 1;
00972 
00973     TCoeff deltaU[MAX_TB_SIZEY * MAX_TB_SIZEY];
00974     int scalingListType = getScalingListType(tu.cu->predMode, compID);
00975     CHECK(scalingListType >= SCALING_LIST_NUM, "Invalid scaling list");
00976     const uint32_t uiLog2TrWidth = floorLog2(uiWidth);
00977     const uint32_t uiLog2TrHeight = floorLog2(uiHeight);
00978     int *piQuantCoeff = getQuantCoeff(scalingListType, cQP.rem(useTransformSkip), uiLog2TrWidth, uiLog2TrHeight);
00979     const bool disableSMForLFNST = tu.cs->slice->getExplicitScalingListUsed() ? tu.cs->slice->getSPS()->getDisableScalingMatrixForLfnstBlks() : false;
00980     const bool isLfnstApplied = tu.cu->lfnstIdx > 0 && (tu.cu->isSepTree() ? true : isLuma(compID));
00981     const bool disableSMForACT = tu.cs->slice->getSPS()->getScalingMatrixForAlternativeColourSpaceDisabledFlag() && (tu.cs->slice->getSPS()->getScalingMatrixDesignatedColourSpaceFlag() == tu.cu->colorTransform);
00982     const bool enableScalingLists = getUseScalingList(uiWidth, uiHeight, useTransformSkip, isLfnstApplied, disableSMForLFNST, disableSMForACT);
00983 
00984     // for blocks that where width*height != 4^N, the effective scaling applied during transformation cannot be
00985     // compensated by a bit-shift (the quantised result will be sqrt(2) * larger than required).
00986     // The quantScale table and shift is used to compensate for this.
00987     const bool needSqrtAdjustment= TU::needsBlockSizeTrafoScale( tu, compID );
00988     const int defaultQuantisationCoefficient    = g_quantScales[needSqrtAdjustment?1:0][cQP.rem(useTransformSkip)];
00989     int iTransformShift = getTransformShift(channelBitDepth, rect.size(), maxLog2TrDynamicRange) + ( needSqrtAdjustment?-1:0);
00990 
00991     if (useTransformSkip && sps.getSpsRangeExtension().getExtendedPrecisionProcessingFlag())
00992     {
00993       iTransformShift = std::max<int>(0, iTransformShift);
00994     }
00995 
00996     const int iQBits = QUANT_SHIFT + cQP.per(useTransformSkip) + (useTransformSkip ? 0 : iTransformShift);
00997     // QBits will be OK for any internal bit depth as the reduction in transform shift is balanced by an increase in Qp_per due to QpBDOffset
00998 
00999     const int64_t iAdd = int64_t(tu.cs->slice->isIRAP() ? 171 : 85) << int64_t(iQBits - 9);
01000     const int qBits8 = iQBits - 8;
01001 
01002     const uint32_t lfnstIdx = tu.cu->lfnstIdx;
01003     const int maxNumberOfCoeffs = lfnstIdx > 0 ? ((( uiWidth == 4 && uiHeight == 4 ) || ( uiWidth == 8 && uiHeight == 8) ) ? 8 : 16) : piQCoef.area();
01004     memset( piQCoef.buf, 0, sizeof(TCoeff) * piQCoef.area() );
01005 
01006     const ScanElement* scan = g_scanOrder[SCAN_GROUPED_4x4][SCAN_DIAG][gp_sizeIdxInfo->idxFrom(uiWidth)][gp_sizeIdxInfo->idxFrom(uiHeight)];
01007 
01008     for (int uiScanPos = 0; uiScanPos < maxNumberOfCoeffs; uiScanPos++)
01009     {
01010       const int uiBlockPos = scan[uiScanPos].idx;
01011       const TCoeff iLevel   = piCoef.buf[uiBlockPos];
01012       const TCoeff iSign    = (iLevel < 0 ? -1: 1);
01013 
01014       const int64_t  tmpLevel = (int64_t)abs(iLevel) * (enableScalingLists ? piQuantCoeff[uiBlockPos] : defaultQuantisationCoefficient);
01015 
01016       const TCoeff quantisedMagnitude = TCoeff((tmpLevel + iAdd ) >> iQBits);
01017       deltaU[uiBlockPos] = (TCoeff)((tmpLevel - ((int64_t)quantisedMagnitude<<iQBits) )>> qBits8);
01018 
01019       uiAbsSum += quantisedMagnitude;
01020       const TCoeff quantisedCoefficient = quantisedMagnitude * iSign;
01021 
01022       piQCoef.buf[uiBlockPos] = Clip3<TCoeff>( entropyCodingMinimum, entropyCodingMaximum, quantisedCoefficient );
01023     } // for n
01024     if ((tu.cu->bdpcmMode && isLuma(compID)) || (tu.cu->bdpcmModeChroma && isChroma(compID)) )
01025     {
01026       fwdResDPCM( tu, compID );
01027     }
01028     if( cctx.signHiding() )
01029     {
01030       if(uiAbsSum >= 2) //this prevents TUs with only one coefficient of value 1 from being tested
01031       {
01032         xSignBitHidingHDQ(piQCoef.buf, piCoef.buf, deltaU, cctx, maxLog2TrDynamicRange);
01033       }
01034     }
01035   } //if RDOQ
01036   //return;
01037 }
01038 
01039 bool Quant::xNeedRDOQ(TransformUnit &tu, const ComponentID &compID, const CCoeffBuf &pSrc, const QpParam &cQP)
01040 {
01041   const SPS &sps            = *tu.cs->sps;
01042   const CompArea &rect      = tu.blocks[compID];
01043   const uint32_t uiWidth        = rect.width;
01044   const uint32_t uiHeight       = rect.height;
01045   const int channelBitDepth = sps.getBitDepth(toChannelType(compID));
01046 
01047   const CCoeffBuf piCoef    = pSrc;
01048 
01049   const bool useTransformSkip      = (tu.mtsIdx[compID] == MTS_SKIP);
01050   const int  maxLog2TrDynamicRange = sps.getMaxLog2TrDynamicRange(toChannelType(compID));
01051 
01052   int scalingListType = getScalingListType(tu.cu->predMode, compID);
01053   CHECK(scalingListType >= SCALING_LIST_NUM, "Invalid scaling list");
01054 
01055   const uint32_t uiLog2TrWidth  = floorLog2(uiWidth);
01056   const uint32_t uiLog2TrHeight = floorLog2(uiHeight);
01057   int *piQuantCoeff         = getQuantCoeff(scalingListType, cQP.rem(useTransformSkip), uiLog2TrWidth, uiLog2TrHeight);
01058 
01059   const bool disableSMForLFNST = tu.cs->slice->getExplicitScalingListUsed() ? tu.cs->slice->getSPS()->getDisableScalingMatrixForLfnstBlks() : false;
01060   const bool isLfnstApplied = tu.cu->lfnstIdx > 0 && (tu.cu->isSepTree() ? true : isLuma(compID));
01061   const bool disableSMForACT = tu.cs->slice->getSPS()->getScalingMatrixForAlternativeColourSpaceDisabledFlag() && (tu.cs->slice->getSPS()->getScalingMatrixDesignatedColourSpaceFlag() == tu.cu->colorTransform);
01062   const bool enableScalingLists = getUseScalingList(uiWidth, uiHeight, (useTransformSkip != 0), isLfnstApplied, disableSMForLFNST, disableSMForACT);
01063 
01064   /* for 422 chroma blocks, the effective scaling applied during transformation is not a power of 2, hence it cannot be
01065     * implemented as a bit-shift (the quantised result will be sqrt(2) * larger than required). Alternatively, adjust the
01066     * uiLog2TrSize applied in iTransformShift, such that the result is 1/sqrt(2) the required result (i.e. smaller)
01067     * Then a QP+3 (sqrt(2)) or QP-3 (1/sqrt(2)) method could be used to get the required result
01068     */
01069   const bool needSqrtAdjustment= TU::needsBlockSizeTrafoScale( tu, compID );
01070   const int defaultQuantisationCoefficient    = g_quantScales[needSqrtAdjustment?1:0][cQP.rem(useTransformSkip)];
01071   int iTransformShift = getTransformShift(channelBitDepth, rect.size(), maxLog2TrDynamicRange) + (needSqrtAdjustment?-1:0);
01072 
01073   if (useTransformSkip && sps.getSpsRangeExtension().getExtendedPrecisionProcessingFlag())
01074   {
01075     iTransformShift = std::max<int>(0, iTransformShift);
01076   }
01077 
01078 
01079   const int iQBits = QUANT_SHIFT + cQP.per(useTransformSkip) + iTransformShift;
01080   assert(iQBits>=0);
01081   // QBits will be OK for any internal bit depth as the reduction in transform shift is balanced by an increase in Qp_per due to QpBDOffset
01082 
01083   // iAdd is different from the iAdd used in normal quantization
01084   const int64_t iAdd = int64_t(compID == COMPONENT_Y ? 171 : 256) << (iQBits - 9);
01085 
01086   for (int uiBlockPos = 0; uiBlockPos < rect.area(); uiBlockPos++)
01087   {
01088     const TCoeff iLevel   = piCoef.buf[uiBlockPos];
01089     const int64_t  tmpLevel = (int64_t)abs(iLevel) * (enableScalingLists ? piQuantCoeff[uiBlockPos] : defaultQuantisationCoefficient);
01090     const TCoeff quantisedMagnitude = TCoeff((tmpLevel + iAdd ) >> iQBits);
01091 
01092     if (quantisedMagnitude != 0)
01093     {
01094       return true;
01095     }
01096   } // for n
01097   return false;
01098 }
01099 
01100 
01101 void Quant::transformSkipQuantOneSample(TransformUnit &tu, const ComponentID &compID, const TCoeff &resiDiff, TCoeff &coeff, const uint32_t &uiPos, const QpParam &cQP, const bool bUseHalfRoundingPoint)
01102 {
01103   const SPS           &sps = *tu.cs->sps;
01104   const CompArea      &rect                           = tu.blocks[compID];
01105   const uint32_t           uiWidth                        = rect.width;
01106   const uint32_t           uiHeight                       = rect.height;
01107   const int            maxLog2TrDynamicRange          = sps.getMaxLog2TrDynamicRange(toChannelType(compID));
01108   const int            channelBitDepth                = sps.getBitDepth(toChannelType(compID));
01109   const int            iTransformShift                = getTransformShift(channelBitDepth, rect.size(), maxLog2TrDynamicRange);
01110   const int            scalingListType                = getScalingListType(tu.cu->predMode, compID);
01111 
01112   const bool           disableSMForLFNST = tu.cs->slice->getExplicitScalingListUsed() ? tu.cs->slice->getSPS()->getDisableScalingMatrixForLfnstBlks() : false;
01113   const bool           isLfnstApplied = tu.cu->lfnstIdx > 0 && (tu.cu->isSepTree() ? true : isLuma(compID));
01114   const bool           disableSMForACT = tu.cs->slice->getSPS()->getScalingMatrixForAlternativeColourSpaceDisabledFlag() && (tu.cs->slice->getSPS()->getScalingMatrixDesignatedColourSpaceFlag() == tu.cu->colorTransform);
01115   const bool           enableScalingLists = getUseScalingList(uiWidth, uiHeight, true, isLfnstApplied, disableSMForLFNST, disableSMForACT);
01116   const bool           useTransformSkip = (tu.mtsIdx[compID] == MTS_SKIP);
01117   const int            defaultQuantisationCoefficient = g_quantScales[0][cQP.rem(useTransformSkip)];
01118 
01119   CHECK( scalingListType >= SCALING_LIST_NUM, "Invalid scaling list" );
01120 
01121   const uint32_t uiLog2TrWidth      = floorLog2(uiWidth);
01122   const uint32_t uiLog2TrHeight     = floorLog2(uiHeight);
01123   const int *const piQuantCoeff = getQuantCoeff(scalingListType, cQP.rem(useTransformSkip), uiLog2TrWidth, uiLog2TrHeight);
01124 
01125   /* for 422 chroma blocks, the effective scaling applied during transformation is not a power of 2, hence it cannot be
01126   * implemented as a bit-shift (the quantised result will be sqrt(2) * larger than required). Alternatively, adjust the
01127   * uiLog2TrSize applied in iTransformShift, such that the result is 1/sqrt(2) the required result (i.e. smaller)
01128   * Then a QP+3 (sqrt(2)) or QP-3 (1/sqrt(2)) method could be used to get the required result
01129   */
01130   const int iQBits = QUANT_SHIFT + cQP.per(useTransformSkip) + (useTransformSkip ? 0 : iTransformShift);
01131   // QBits will be OK for any internal bit depth as the reduction in transform shift is balanced by an increase in Qp_per due to QpBDOffset
01132   const int iAdd = int64_t(bUseHalfRoundingPoint ? 256 : (tu.cs->slice->isIRAP() ? 171 : 85)) << int64_t(iQBits - 9);
01133   TCoeff transformedCoefficient;
01134 
01135   // transform-skip
01136   if (iTransformShift >= 0)
01137   {
01138     transformedCoefficient = resiDiff << iTransformShift;
01139   }
01140   else // for very high bit depths
01141   {
01142     const int iTrShiftNeg  = -iTransformShift;
01143     const int offset       = 1 << (iTrShiftNeg - 1);
01144     transformedCoefficient = ( resiDiff + offset ) >> iTrShiftNeg;
01145   }
01146 
01147   // quantization
01148   const TCoeff iSign = (transformedCoefficient < 0 ? -1: 1);
01149 
01150   const int quantisationCoefficient = enableScalingLists ? piQuantCoeff[uiPos] : defaultQuantisationCoefficient;
01151 
01152   const int64_t tmpLevel = (int64_t)abs(transformedCoefficient) * quantisationCoefficient;
01153 
01154   const TCoeff quantisedCoefficient = (TCoeff((tmpLevel + iAdd ) >> iQBits)) * iSign;
01155 
01156   const TCoeff entropyCodingMinimum = -(1 << maxLog2TrDynamicRange);
01157   const TCoeff entropyCodingMaximum =  (1 << maxLog2TrDynamicRange) - 1;
01158   coeff = Clip3<TCoeff>( entropyCodingMinimum, entropyCodingMaximum, quantisedCoefficient );
01159 }
01160 
01161 void Quant::invTrSkipDeQuantOneSample(TransformUnit &tu, const ComponentID &compID, const TCoeff &inSample, Pel &reconSample, const uint32_t &uiPos, const QpParam &cQP)
01162 {
01163   const SPS           &sps                    = *tu.cs->sps;
01164   const CompArea      &rect                   = tu.blocks[compID];
01165   const uint32_t           uiWidth                = rect.width;
01166   const uint32_t           uiHeight               = rect.height;
01167   const int            QP_per                 = cQP.per(tu.mtsIdx[compID] == MTS_SKIP);
01168   const int            QP_rem                 = cQP.rem(tu.mtsIdx[compID] == MTS_SKIP);
01169   const int            maxLog2TrDynamicRange  = sps.getMaxLog2TrDynamicRange(toChannelType(compID));
01170   const int            channelBitDepth        = sps.getBitDepth(toChannelType(compID));
01171   const int            iTransformShift        = getTransformShift(channelBitDepth, rect.size(), maxLog2TrDynamicRange);
01172   const int            scalingListType        = getScalingListType(tu.cu->predMode, compID);
01173   
01174   const bool           disableSMForLFNST = tu.cs->slice->getExplicitScalingListUsed() ? tu.cs->slice->getSPS()->getDisableScalingMatrixForLfnstBlks() : false;
01175   const bool           isLfnstApplied = tu.cu->lfnstIdx > 0 && (tu.cu->isSepTree() ? true : isLuma(compID));
01176   const bool           disableSMForACT = tu.cs->slice->getSPS()->getScalingMatrixForAlternativeColourSpaceDisabledFlag() && (tu.cs->slice->getSPS()->getScalingMatrixDesignatedColourSpaceFlag() == tu.cu->colorTransform);
01177   const bool           enableScalingLists = getUseScalingList(uiWidth, uiHeight, true, isLfnstApplied, disableSMForLFNST, disableSMForACT);
01178   CHECK(scalingListType >= SCALING_LIST_NUM, "Invalid scaling list");
01179 
01180   const bool isTransformSkip = (tu.mtsIdx[compID] == MTS_SKIP);
01181   const int rightShift = (IQUANT_SHIFT - ((isTransformSkip ? 0 : iTransformShift) + QP_per)) + (enableScalingLists ? LOG2_SCALING_LIST_NEUTRAL_VALUE : 0);
01182 
01183   const TCoeff transformMinimum = -(1 << maxLog2TrDynamicRange);
01184   const TCoeff transformMaximum =  (1 << maxLog2TrDynamicRange) - 1;
01185 
01186   // De-quantisation
01187 
01188   TCoeff dequantisedSample;
01189 
01190   if (enableScalingLists)
01191   {
01192     const uint32_t             dequantCoefBits = 1 + IQUANT_SHIFT + SCALING_LIST_BITS;
01193     const uint32_t             targetInputBitDepth = std::min<uint32_t>((maxLog2TrDynamicRange + 1), (((sizeof(Intermediate_Int) * 8) + rightShift) - dequantCoefBits));
01194 
01195     const Intermediate_Int inputMinimum = -(1 << (targetInputBitDepth - 1));
01196     const Intermediate_Int inputMaximum =  (1 << (targetInputBitDepth - 1)) - 1;
01197 
01198     const uint32_t uiLog2TrWidth  = floorLog2(uiWidth);
01199     const uint32_t uiLog2TrHeight = floorLog2(uiHeight);
01200     int *piDequantCoef        = getDequantCoeff(scalingListType, QP_rem, uiLog2TrWidth, uiLog2TrHeight);
01201 
01202     if (rightShift > 0)
01203     {
01204       const Intermediate_Int iAdd = (Intermediate_Int) 1 << (rightShift - 1);
01205       const TCoeff           clipQCoef = TCoeff(Clip3<Intermediate_Int>(inputMinimum, inputMaximum, inSample));
01206       const Intermediate_Int iCoeffQ = ((Intermediate_Int(clipQCoef) * piDequantCoef[uiPos]) + iAdd) >> rightShift;
01207 
01208       dequantisedSample = TCoeff(Clip3<Intermediate_Int>(transformMinimum, transformMaximum, iCoeffQ));
01209     }
01210     else
01211     {
01212       const int              leftShift = -rightShift;
01213       const TCoeff           clipQCoef = TCoeff(Clip3<Intermediate_Int>(inputMinimum, inputMaximum, inSample));
01214       const Intermediate_Int iCoeffQ = (Intermediate_Int(clipQCoef) * piDequantCoef[uiPos]) << leftShift;
01215 
01216       dequantisedSample = TCoeff(Clip3<Intermediate_Int>(transformMinimum, transformMaximum, iCoeffQ));
01217     }
01218   }
01219   else
01220   {
01221     const int scale = g_invQuantScales[0][QP_rem];
01222     const int scaleBits = (IQUANT_SHIFT + 1);
01223 
01224     const uint32_t             targetInputBitDepth = std::min<uint32_t>((maxLog2TrDynamicRange + 1), (((sizeof(Intermediate_Int) * 8) + rightShift) - scaleBits));
01225     const Intermediate_Int inputMinimum = -(1 << (targetInputBitDepth - 1));
01226     const Intermediate_Int inputMaximum = (1 << (targetInputBitDepth - 1)) - 1;
01227 
01228     if (rightShift > 0)
01229     {
01230       const Intermediate_Int iAdd = (Intermediate_Int) 1 << (rightShift - 1);
01231       const TCoeff           clipQCoef = TCoeff(Clip3<Intermediate_Int>(inputMinimum, inputMaximum, inSample));
01232       const Intermediate_Int iCoeffQ = (Intermediate_Int(clipQCoef) * scale + iAdd) >> rightShift;
01233 
01234       dequantisedSample = TCoeff(Clip3<Intermediate_Int>(transformMinimum, transformMaximum, iCoeffQ));
01235     }
01236     else
01237     {
01238       const int              leftShift = -rightShift;
01239       const TCoeff           clipQCoef = TCoeff(Clip3<Intermediate_Int>(inputMinimum, inputMaximum, inSample));
01240       const Intermediate_Int iCoeffQ = (Intermediate_Int(clipQCoef) * scale) << leftShift;
01241 
01242       dequantisedSample = TCoeff(Clip3<Intermediate_Int>(transformMinimum, transformMaximum, iCoeffQ));
01243     }
01244   }
01245 
01246   // Inverse transform-skip
01247   reconSample = Pel(dequantisedSample);
01248 }
01249 
01250 void Quant::lambdaAdjustColorTrans(bool forward)
01251 {
01252   if (m_resetStore)
01253   {
01254     for (uint8_t component = 0; component < MAX_NUM_COMPONENT; component++)
01255     {
01256       ComponentID compID = (ComponentID)component;
01257       int       delta_QP = DELTA_QP_ACT[compID];
01258       double lamdbaAdjustRate = pow(2.0, delta_QP / 3.0);
01259 
01260       m_lambdasStore[0][component] = m_lambdas[component];
01261       m_lambdasStore[1][component] = m_lambdas[component] * lamdbaAdjustRate;
01262     }
01263     m_resetStore = false;
01264   }
01265 
01266   if (forward)
01267   {
01268     CHECK(m_pairCheck == 1, "lambda has been already adjusted");
01269     m_pairCheck = 1;
01270   }
01271   else
01272   {
01273     CHECK(m_pairCheck == 0, "lambda has not been adjusted");
01274     m_pairCheck = 0;
01275   }
01276 
01277   for (uint8_t component = 0; component < MAX_NUM_COMPONENT; component++)
01278   {
01279     m_lambdas[component] = m_lambdasStore[m_pairCheck][component];
01280   }
01281 }
